using System.Text.Json;
using ModelContextProtocol.Server;

/// <summary>
/// Exposes application configuration as MCP resources.
/// Clients discover these via resources/list and read them via resources/read.
/// </summary>
[McpServerResourceType]
public static class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["appName"]     = "McpHttpServer",
        ["version"]     = "1.0.0",
        ["environment"] = "Production",
        ["features"]    = new Dictionary<string, bool>
        {
            ["darkMode"]      = true,
            ["notifications"] = true,
            ["betaAccess"]    = false,
        },
    };

    /// <summary>
    /// Returns the full application configuration as JSON.
    /// URI: config://app
    /// </summary>
    [McpServerResource(UriTemplate = "config://app",
                       Name        = "app-config",
                       MimeType    = "application/json")]
    public static string GetAppConfig()
        => JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });

    /// <summary>
    /// Returns a single configuration value by key.
    /// URI template: config://app/{key}  (e.g. config://app/version)
    /// </summary>
    [McpServerResource(UriTemplate = "config://app/{key}",
                       Name        = "app-config-value",
                       MimeType    = "application/json")]
    public static string GetConfigValue(string key)
    {
        if (AppConfig.TryGetValue(key, out var value))
            return JsonSerializer.Serialize(value, new JsonSerializerOptions { WriteIndented = true });

        return JsonSerializer.Serialize(new { error = $"Key '{key}' not found" });
    }
}

